import{c as r,S as a,j as t,m as l}from"./chunks/framework.VsSDrsS3.js";const c=JSON.parse('{"title":"开发工具 & 常用资源","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/devops/dev-tools.md","filePath":"knowledge/devops/dev-tools.md","lastUpdated":1780046787000}'),o={name:"knowledge/devops/dev-tools.md"};function s(n,e,i,h,g,d){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="开发工具-常用资源" tabindex="-1">开发工具 &amp; 常用资源 <a class="header-anchor" href="#开发工具-常用资源" aria-label="Permalink to “开发工具 &amp; 常用资源”">​</a></h1><h2 id="开发效率" tabindex="-1">开发效率 <a class="header-anchor" href="#开发效率" aria-label="Permalink to “开发效率”">​</a></h2><ul><li><strong><a href="https://www.u-tools.cn/" target="_blank" rel="noreferrer">uTools</a></strong> — Windows/Mac 万能工具箱，插件市场丰富，一键呼出。支持 JSON 格式化、颜色转换、翻译、计算等</li><li><strong><a href="https://naotu.baidu.com/home" target="_blank" rel="noreferrer">百度脑图</a></strong> — 在线思维导图，免费、免安装、云端保存</li><li><strong><a href="https://cosy247.github.io/BlogByCosy/NPMRegistryManager.html" target="_blank" rel="noreferrer">NRM</a></strong> — NPM 镜像源管理工具，一键切换 npm 源（npm/淘宝/腾讯等）</li><li><strong><a href="https://caniuse.com/" target="_blank" rel="noreferrer">Can I use</a></strong> — 查询 CSS/JS/HTML 特性的浏览器兼容性</li></ul><h2 id="在线工具" tabindex="-1">在线工具 <a class="header-anchor" href="#在线工具" aria-label="Permalink to “在线工具”">​</a></h2><ul><li><strong><a href="https://www.toolhelper.cn/JSON/JSONFormat" target="_blank" rel="noreferrer">JSON 格式化</a></strong> — 在线 JSON 格式化、压缩、校验</li><li><strong><a href="https://www.toolhelper.cn/Color/RGBToHex" target="_blank" rel="noreferrer">颜色代码转换</a></strong> — RGB/HEX/HSL 互转</li><li><strong><a href="https://33tool.com/image_color/" target="_blank" rel="noreferrer">图片颜色分析</a></strong> — 提取图片主色调</li><li><strong><a href="https://www.iloveimg.com/zh-cn" target="_blank" rel="noreferrer">iLoveIMG</a></strong> — 图片批量压缩、裁剪、格式转换</li><li><strong><a href="https://tool.browser.qq.com/" target="_blank" rel="noreferrer">帮小忙</a></strong> — 腾讯 QQ 浏览器工具箱，证件照、OCR、PDF 处理等</li><li><strong><a href="https://tool.oschina.net/" target="_blank" rel="noreferrer">OSCHINA 在线工具</a></strong> — 代码格式化、加密解密、时间戳转换</li><li><strong><a href="https://www.taojuju.com/" target="_blank" rel="noreferrer">壁纸样机生成器</a></strong> — 免费生成 iPhone/iPad/Mac 壁纸效果图</li><li><strong><a href="https://www.ipaddress.com/" target="_blank" rel="noreferrer">IPAddress.com</a></strong> — 查询域名 IP、DNS 解析</li></ul><h2 id="媒体-动画" tabindex="-1">媒体 &amp; 动画 <a class="header-anchor" href="#媒体-动画" aria-label="Permalink to “媒体 &amp; 动画”">​</a></h2><ul><li><strong><a href="https://lottiefiles.com/free-animations/colors" target="_blank" rel="noreferrer">LottieFiles</a></strong> — 免费 Lottie 动画下载（JSON/GIF/MP4）</li><li><strong><a href="https://vue-bits.dev/" target="_blank" rel="noreferrer">Vue Bits</a></strong> — Vue 动画组件库</li><li><strong><a href="https://soundit.app/" target="_blank" rel="noreferrer">SoundIt App</a></strong> — 音频处理工具</li><li><strong><a href="https://www.filetools.com.cn/zh/convert/document/epub-to-txt.html" target="_blank" rel="noreferrer">EPUB 转 TXT</a></strong> — 电子书格式转换</li></ul><h2 id="内网穿透" tabindex="-1">内网穿透 <a class="header-anchor" href="#内网穿透" aria-label="Permalink to “内网穿透”">​</a></h2><ul><li><strong><a href="https://www.natfrp.com/user/" target="_blank" rel="noreferrer">SakuraFrp</a></strong> — 免费内网穿透，国内用户友好。⚠️ 免费服务可能随时调整策略，重要服务建议自建或使用付费方案作为备份</li><li><strong><a href="https://eastondev.com/blog/zh/posts/dev/20251130-cloudflare-tunnel-guide/" target="_blank" rel="noreferrer">Cloudflare Tunnel</a></strong> — Cloudflare 官方方案（已在 devops/self-hosting.md 详述）</li></ul><h2 id="自动化" tabindex="-1">自动化 <a class="header-anchor" href="#自动化" aria-label="Permalink to “自动化”">​</a></h2><ul><li><strong><a href="https://github.com/dreammis/social-auto-upload" target="_blank" rel="noreferrer">social-auto-upload</a></strong> — 一键分发视频到抖音/小红书/B站/YouTube/TikTok</li><li><strong><a href="https://www.mapeditor.org/" target="_blank" rel="noreferrer">Tiled</a></strong> — 开源 2D 地图编辑器，适合游戏开发</li></ul><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to “其他”">​</a></h2><ul><li><strong><a href="https://github.xyxiao.cn/vue-cropper/" target="_blank" rel="noreferrer">vue-cropper</a></strong> — Vue 图片裁剪组件</li><li>⚠️ 避免从第三方站点下载 DLL（恶意软件风险），优先通过 Microsoft 官方渠道或系统更新修复缺失的 DLL</li></ul><h2 id="powershell-执行策略" tabindex="-1">PowerShell 执行策略 <a class="header-anchor" href="#powershell-执行策略" aria-label="Permalink to “PowerShell 执行策略”">​</a></h2><p>运行 .ps1 脚本时报&quot;因为在此系统上禁止运行脚本&quot;。</p><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-ExecutionPolicy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope CurrentUser RemoteSigned</span></span></code></pre></div><p>以管理员身份运行，RemoteSigned 允许本地脚本，远程脚本需签名。</p><h2 id="obs-推流" tabindex="-1">OBS 推流 <a class="header-anchor" href="#obs-推流" aria-label="Permalink to “OBS 推流”">​</a></h2><p>B 站直播姬本质是定制版 OBS，可以获取推流地址后使用原生 OBS 推流。获取推流地址：开播 → 直播设置 → 推流地址（rtmp:// 开头）。OBS 设置 → 推流 → 服务选&quot;自定义&quot; → 填入服务器和串流密钥。</p>',19)])])}const f=r(o,[["render",s]]);export{c as __pageData,f as default};
